# Let's try a direct construction. Known: incidence graphs of generalized polygons have high girth.
# Heawood graph has girth 6, 14 vertices.
# For girth 7 with many edges on small n, we can try specific constructions.

# Strategy: random greedy + local search for girth 7.
import random

def has_short_cycle(adj, u, v, max_len=6):
    # check if adding edge u-v creates cycle of length <= max_len
    # i.e., shortest path from u to v in current graph <= max_len - 1
    from collections import deque
    dist = {u: 0}
    q = deque([u])
    while q:
        x = q.popleft()
        if dist[x] >= max_len - 1:
            continue
        for y in adj[x]:
            if y == v and x != u:
                return True
            if y not in dist:
                dist[y] = dist[x] + 1
                q.append(y)
    return v in dist and dist[v] <= max_len - 1

def try_build(n, target, seed):
    random.seed(seed)
    adj = {i: set() for i in range(n)}
    edges = []
    candidates = [(i,j) for i in range(n) for j in range(i+1,n)]
    random.shuffle(candidates)
    for u,v in candidates:
        if has_short_cycle(adj, u, v, 6):
            continue
        adj[u].add(v); adj[v].add(u)
        edges.append((u,v))
    return edges, adj

best = 0
best_edges = None
for s in range(200):
    e, a = try_build(19, 37, s)
    if len(e) > best:
